<script setup lang="ts">
import { shallowRef } from 'vue'
import IdentityCandidateBatch from '../components/IdentityCandidateBatch.vue'
import IdentityNamesEditor from '../components/IdentityNamesEditor.vue'
import IdentityCandidateForm from '../components/IdentityCandidateForm.vue'
import IdentityDecisionForm from '../components/IdentityDecisionForm.vue'
import IdentityTargetPreview from '../components/IdentityTargetPreview.vue'
import { useIdentityReview } from '../composables/useIdentityReview'
import { identityActions, identityChange, identityProviders, identityStatuses } from '../types/identityReview'
const {rows,detail,authorized,provider,status,loading,saving,error,message,load,select,login,logout,create,decide,expireSession}=useIdentityReview()
const username=shallowRef(''),password=shallowRef(''),batchBusy=shallowRef(false),namesBusy=shallowRef(false)
async function namesChanged(feedback:string){message.value=feedback;await load()}
async function signIn(){try{await login(username.value,password.value)}finally{password.value=''}}
void load()
</script>
<template><section class="page-intro"><h1>跨来源身份核验</h1><p>核对来源身份与现有档案的对应关系；候选和同名资料不会自动合并实体。</p></section><p v-if="error" class="feedback error" role="alert">{{ error }} <button :disabled="loading||saving" @click="load()">重新读取</button></p><p v-if="message" class="feedback" role="status">{{ message }}</p><p v-if="loading" role="status">正在读取…</p><section v-if="!authorized&&!loading" class="panel"><h2>维护会话</h2><p>仅供已启用身份维护的环境及现有管理员使用。普通片单关联不提供维护权限。</p><form class="session-form" @submit.prevent="signIn"><label>维护账号<input v-model="username" required autocomplete="username"></label><label>密码<input v-model="password" required type="password" autocomplete="current-password"></label><button :disabled="namesBusy||batchBusy||saving">建立维护会话</button></form></section><template v-if="authorized"><div class="toolbar"><label>来源<select v-model="provider" :disabled="namesBusy||batchBusy||saving" @change="load()"><option value="">全部来源</option><option v-for="p in identityProviders" :key="p">{{ p }}</option></select></label><label>状态<select v-model="status" :disabled="namesBusy||batchBusy||saving" @change="load()"><option value="">全部状态</option><option v-for="(label,code) in identityStatuses" :key="code" :value="code">{{ label }}</option></select></label><button :disabled="namesBusy||batchBusy||saving||loading" @click="load()">读取最新</button><button :disabled="namesBusy||batchBusy||saving" @click="logout">退出维护会话</button></div><IdentityCandidateBatch :busy="namesBusy||saving||loading" @busy="batchBusy=$event" @changed="load()" @unauthorized="expireSession()"/><IdentityCandidateForm :busy="namesBusy||batchBusy||saving" @save="create"/><div class="identity-workspace"><section class="panel"><h2>身份记录</h2><button v-for="row in rows" :key="row.id" class="identity-row" :disabled="namesBusy||batchBusy||saving" @click="select(row.id)"><strong>{{ row.provider }} · {{ row.providerId }}</strong><span>{{ identityStatuses[row.status] }}</span><small>{{ row.canonicalUid }}</small></button><p v-if="!rows.length">没有符合条件的记录。</p><button v-if="rows.length===30" :disabled="namesBusy||batchBusy||saving||loading" @click="load(rows[rows.length-1]!.id)">读取更早记录</button></section><section v-if="detail" class="panel"><h2>{{ detail.identity.provider }} · {{ detail.identity.providerId }}</h2><p>{{ identityStatuses[detail.identity.status] }} · {{ detail.identity.canonicalUid }}</p><IdentityTargetPreview :uid="detail.identity.canonicalUid" :disabled="namesBusy||batchBusy||saving"/><p><a :href="detail.identity.sourceUrl" target="_blank" rel="noopener noreferrer">核对来源原页</a> · 修订 {{ detail.identity.sourceRevision||'未记录' }}</p><p>{{ detail.identity.licenseLabel }}</p><pre class="proof">{{ detail.identity.evidenceText||'旧记录尚缺核验原文；候选须先补充再审核。' }}</pre><IdentityDecisionForm :identity="detail.identity" :busy="namesBusy||batchBusy||saving" @save="decide"/><IdentityNamesEditor :identity="detail.identity" :busy="saving||batchBusy" @busy="namesBusy=$event" @changed="namesChanged" @unauthorized="expireSession()"/><h3>最近100次操作记录</h3><article v-for="event in detail.history" :key="event.id" class="history"><strong>{{ identityActions[event.action]||event.action }}</strong><p>{{ identityChange(event) }}</p><p>{{ event.reason }}</p><small>维护者 #{{ event.actorId }} · {{ event.createdAt }}</small></article></section><p v-else class="panel">选择一条身份记录，逐项核对来源、目标和历史。</p></div></template></template>
<style scoped>.identity-workspace{display:grid;grid-template-columns:minmax(250px,1fr) minmax(0,2fr);gap:24px}.identity-row{display:grid;width:100%;gap:7px;text-align:left;margin:8px 0;overflow-wrap:anywhere}.identity-row small{font-size:11px}.proof{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;background:#f4f7ef;padding:16px}.history{border-top:1px solid #dce6d1;padding:16px 0;overflow-wrap:anywhere}.session-form{display:grid;gap:16px;max-width:400px}p{line-height:1.8;overflow-wrap:anywhere}a{text-decoration:underline}@media(max-width:750px){.identity-workspace{grid-template-columns:1fr}}</style>
